class Solution {
  private long[] cnt;
  private long[] sum;
  private int size;

  private void add(int pos, int c, long v) {
    for (; pos <= size; pos += pos & -pos) {
      cnt[pos] += c;
      sum[pos] += v;
    }
  }

  public long minOperations(int[] nums, int x, int k) {
    int n = nums.length;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    java.util.Arrays.sort(order, (a, b) -> Integer.compare(nums[a], nums[b]));
    int[] rank = new int[n];
    long[] valueAt = new long[n + 1];
    for (int r = 0; r < n; r++) {
      rank[order[r]] = r + 1;
      valueAt[r + 1] = nums[order[r]];
    }
    size = n;
    cnt = new long[n + 1];
    sum = new long[n + 1];
    int top = 1;
    while ((top << 1) <= n) top <<= 1;
    long total = 0;
    int windows = n - x + 1;
    long[] cost = new long[windows];
    int kth = (x + 1) / 2;
    for (int i = 0; i < n; i++) {
      add(rank[i], 1, nums[i]);
      total += nums[i];
      if (i >= x) {
        add(rank[i - x], -1, -nums[i - x]);
        total -= nums[i - x];
      }
      if (i >= x - 1) {
        int pos = 0;
        long rem = kth, acc = 0;
        for (int pw = top; pw > 0; pw >>= 1) {
          if (pos + pw <= n && cnt[pos + pw] < rem) {
            pos += pw;
            rem -= cnt[pos];
            acc += sum[pos];
          }
        }
        long med = valueAt[pos + 1];
        long left = acc + med;
        cost[i - x + 1] = med * kth - left + (total - left) - med * (x - kth);
      }
    }
    long INF = Long.MAX_VALUE / 4;
    long[] prev = new long[n + 1];
    for (int j = 1; j <= k; j++) {
      long[] cur = new long[n + 1];
      java.util.Arrays.fill(cur, INF);
      for (int i = 1; i <= n; i++) {
        cur[i] = cur[i - 1];
        if (i >= x && prev[i - x] < INF) cur[i] = Math.min(cur[i], prev[i - x] + cost[i - x]);
      }
      prev = cur;
    }
    return prev[n];
  }
}
